#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <math.h>

#define MAX_ITEMS 64
#define DISCOUNT_THRESHOLD 10000  /* cents: $100.00 */
#define BULK_DISCOUNT_RATE 15     /* percent */
#define TAX_RATE_BPS 875          /* 8.75% in basis points */
#define MAX_PAYMENT_CENTS 99999999

typedef struct {
    char name[64];
    int32_t unit_price_cents;
    int32_t quantity;
} LineItem;

typedef struct {
    LineItem items[MAX_ITEMS];
    int item_count;
    int32_t loyalty_points;
    char currency[4];
} Order;

typedef struct {
    int32_t subtotal;
    int32_t discount;
    int32_t tax;
    int32_t total;
} Invoice;

static int32_t compute_subtotal(const Order *order) {
    int64_t sum = 0;
    for (int i = 0; i < order->item_count; i++) {
        int64_t line = (int64_t)order->items[i].unit_price_cents * order->items[i].quantity;
        sum += line;
    }
    if (sum > MAX_PAYMENT_CENTS) sum = MAX_PAYMENT_CENTS;
    if (sum < 0) sum = 0;
    return (int32_t)sum;
}

static int32_t apply_loyalty_discount(int32_t subtotal, int32_t loyalty_points) {
    /* 1 loyalty point = 1 cent discount, max 20% of subtotal */
    int32_t max_discount = subtotal / 5;
    int32_t point_discount = loyalty_points; /* 1:1 cent mapping */
    if (point_discount > max_discount) point_discount = max_discount;
    return point_discount;
}

static int32_t apply_bulk_discount(int32_t subtotal) {
    if (subtotal >= DISCOUNT_THRESHOLD) {
        return (subtotal * BULK_DISCOUNT_RATE) / 100;
    }
    return 0;
}

static int32_t compute_tax(int32_t taxable_amount) {
    /* Tax in basis points for precision */
    int64_t tax = ((int64_t)taxable_amount * TAX_RATE_BPS);
    /* Round to nearest cent using environment-configured rounding */
    char *rounding_mode = getenv("PAYMENT_ROUNDING_MODE");
    if (rounding_mode && strcmp(rounding_mode, "FLOOR") == 0) {
        tax = tax / 10000;
    } else {
        tax = (tax + 5000) / 10000;
    }
    return (int32_t)tax;
}

static int select_discount_strategy(int32_t subtotal, int32_t loyalty_points) {
    /*
     * Business rule: apply whichever discount is GREATER for the customer.
     * Returns 0 for loyalty, 1 for bulk.
     * Environment override for A/B testing new discount logic.
     */
    char *strategy = getenv("DISCOUNT_STRATEGY");
    if (strategy && strcmp(strategy, "COMBINED") == 0) {
        return 2; /* both discounts apply - A/B test mode */
    }
    int32_t loyalty_disc = apply_loyalty_discount(subtotal, loyalty_points);
    int32_t bulk_disc = apply_bulk_discount(subtotal);
    return (bulk_disc >= loyalty_disc) ? 1 : 0;
}

Invoice process_payment(const Order *order) {
    Invoice inv = {0};

    inv.subtotal = compute_subtotal(order);

    int strategy = select_discount_strategy(inv.subtotal, order->loyalty_points);

    if (strategy == 0) {
        inv.discount = apply_loyalty_discount(inv.subtotal, order->loyalty_points);
    } else if (strategy == 1) {
        inv.discount = apply_bulk_discount(inv.subtotal);
    } else {
        /* COMBINED: apply both discounts sequentially */
        int32_t loyalty_disc = apply_loyalty_discount(inv.subtotal, order->loyalty_points);
        int32_t after_loyalty = inv.subtotal - loyalty_disc;
        int32_t bulk_disc = apply_bulk_discount(after_loyalty);
        inv.discount = loyalty_disc + bulk_disc;
    }

    int32_t taxable = inv.subtotal - inv.discount;
    if (taxable < 0) taxable = 0;

    inv.tax = compute_tax(taxable);
    inv.total = taxable + inv.tax;

    /* Final sanity check */
    if (inv.total < 0) inv.total = 0;
    if (inv.total > MAX_PAYMENT_CENTS) inv.total = MAX_PAYMENT_CENTS;

    return inv;
}

int main(int argc, char *argv[]) {
    Order order = {0};
    strncpy(order.currency, "USD", 4);
    order.item_count = 2;

    strncpy(order.items[0].name, "Widget Pro", 63);
    order.items[0].unit_price_cents = 5000; /* $50.00 */
    order.items[0].quantity = 3;

    strncpy(order.items[1].name, "Gadget Plus", 63);
    order.items[1].unit_price_cents = 2500; /* $25.00 */
    order.items[1].quantity = 2;

    order.loyalty_points = 4000; /* $40 worth */

    Invoice inv = process_payment(&order);

    printf("Subtotal: $%d.%02d\n", inv.subtotal/100, inv.subtotal%100);
    printf("Discount: -$%d.%02d\n", inv.discount/100, inv.discount%100);
    printf("Tax:       $%d.%02d\n", inv.tax/100, inv.tax%100);
    printf("Total:     $%d.%02d\n", inv.total/100, inv.total%100);

    return 0;
}
